public class InnerHarnessHarnessToolConfigurationFactory(Action<Humidifier.BedrockAgentCore.HarnessTypes.HarnessToolConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.HarnessTypes.HarnessToolConfiguration>
{

    internal InnerHarnessHarnessRemoteMcpConfigFactory RemoteMcpFactory { get; set; }

    internal InnerHarnessHarnessAgentCoreCodeInterpreterConfigFactory AgentCoreCodeInterpreterFactory { get; set; }

    internal InnerHarnessHarnessAgentCoreGatewayConfigFactory AgentCoreGatewayFactory { get; set; }

    internal InnerHarnessHarnessInlineFunctionConfigFactory InlineFunctionFactory { get; set; }

    internal InnerHarnessHarnessAgentCoreBrowserConfigFactory AgentCoreBrowserFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.HarnessTypes.HarnessToolConfiguration Create()
    {
        var harnessToolConfigurationResult = CreateHarnessToolConfiguration();
        factoryAction?.Invoke(harnessToolConfigurationResult);

        return harnessToolConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.HarnessTypes.HarnessToolConfiguration CreateHarnessToolConfiguration()
    {
        var harnessToolConfigurationResult = new Humidifier.BedrockAgentCore.HarnessTypes.HarnessToolConfiguration();

        return harnessToolConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.HarnessTypes.HarnessToolConfiguration result)
    {
        base.CreateChildren(result);

        result.RemoteMcp ??= RemoteMcpFactory?.Build();
        result.AgentCoreCodeInterpreter ??= AgentCoreCodeInterpreterFactory?.Build();
        result.AgentCoreGateway ??= AgentCoreGatewayFactory?.Build();
        result.InlineFunction ??= InlineFunctionFactory?.Build();
        result.AgentCoreBrowser ??= AgentCoreBrowserFactory?.Build();
    }

} // End Of Class

